namespace ks{namespace{PanelVersionPartialTest partialTest=nullptr;using T=PanelVersionTask;using K=T::Kind;using S=T::Stage;struct Point{unsigned location,length;};Point point(const T&t){switch(t.stage()){case S::SetLabel:return{t.kind()==K::LabelA?0xb52u:0xb5eu,6};case S::DispatchLabel:return{t.kind()==K::LabelA?0xb58u:0xb64u,4};case S::AwaitLabel:return{t.kind()==K::LabelA?0xb5cu:0xb68u,2};case S::DispatchVersion:return{0xbda,2};case S::AwaitVersion:case S::JoinPatch:return{0xbdc,2};case S::ReadPrimary:return{0xbde,2};case S::RetainPrimary:return{0xbe0,2};case S::ReadSecondary:return{0xbe2,2};case S::ShiftMajor1:return{0xbe4,2};case S::ShiftMajor2:return{0xbe6,2};case S::ShiftMajor3:return{0xbe8,2};case S::DispatchMajor:return{0xbea,4};case S::AwaitMajor:case S::SetDot:return{0xbee,2};case S::DispatchDot:return{0xbf0,4};case S::AwaitDot:case S::SetMinor:return{0xbf4,2};case S::MaskMinor:return{0xbf6,2};case S::AsciiMinor:return{0xbf8,2};case S::DispatchMinor:return{0xbfa,4};case S::AwaitMinor:return{0xbfe,2};case S::SetPatchDot:return{0xc00,2};case S::DispatchPatchDot:return{0xc02,4};case S::AwaitPatchDot:case S::SetPatchValue:return{0xc06,2};case S::DispatchPatchValue:return{0xc08,4};case S::AwaitPatchValue:return{0xc0c,2};case S::Finish:switch(t.kind()){case K::Noop:return{0xb50,2};case K::LabelA:return{0xb5c,2};case K::LabelB:return{0xb68,2};case K::NoopB:return{0xb6a,2};case K::Version:return{0xbfe,2};default:return{0xc0c,2};}default:throw std::runtime_error("Invalid panel version stage");}}}
bool PanelVersionCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token==h.getSP()){selected=&c;break;}if(!selected&&(pc==0xb50||pc==0xb52||pc==0xb5e||pc==0xb6a||pc==0xbde||pc==0xbda||pc==0xc00)){for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Panel version capacity");selected->emplace(pc==0xb50?K::Noop:pc==0xb52?K::LabelA:pc==0xb5e?K::LabelB:pc==0xb6a?K::NoopB:pc==0xbde?K::Version:pc==0xbda?K::WithPatch:K::Patch,h.getSP());++started;}if(!selected||point((**selected).task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto&v=h.regs;if(t.child()!=T::Child::None)t.resumeChild();auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(t).length);auto cost=t.nextClocks();t.advanceBefore(cost,[&](T::Read r)->uint32_t{switch(r){case T::Read::Source:return uint32_t(v[6].er);case T::Read::Primary:return h.read8(t.source()&0xffffff);case T::Read::Secondary:return h.read8((t.source()+1)&0xffffff);case T::Read::Patch:return uint8_t(v[5].rl);}return 0;});switch(stage){case S::SetLabel:f.move(v[6].er,t.label());break;case S::DispatchLabel:f.call(0x9b8);break;case S::DispatchVersion:f.call(0xbde);break;case S::ReadPrimary:f.move(v[0].rl,t.primary());v[6].er+=1;h.clockI(2);break;case S::RetainPrimary:f.move(v[1].rl,t.primary());break;case S::ReadSecondary:f.move(v[5].rl,t.secondary());break;case S::ShiftMajor1:case S::ShiftMajor2:case S::ShiftMajor3:f.shift(v[0].rl,1,false);break;case S::DispatchMajor:if(uint8_t(v[0].rl)!=t.major())throw std::runtime_error("Version major differs");f.call(0xa02);break;case S::SetDot:case S::SetPatchDot:f.move(v[6].rl,0x2e);break;case S::DispatchDot:case S::DispatchMinor:case S::DispatchPatchDot:f.call(0x976);break;case S::SetMinor:f.move(v[6].rl,t.primary());break;case S::MaskMinor:v[6].rl&=7;value(h,v[6].rl);break;case S::AsciiMinor:v[6].rl=h.add8(v[6].rl,0x30);break;case S::SetPatchValue:f.move(v[0].rl,t.patch());break;case S::DispatchPatchValue:f.call(0x9dc);break;case S::Finish:f.ret();selected->reset();++completed;break;default:break;}bool dispatched=stage==S::DispatchLabel||stage==S::DispatchVersion||stage==S::DispatchMajor||stage==S::DispatchDot||stage==S::DispatchMinor||stage==S::DispatchPatchDot||stage==S::DispatchPatchValue;h.pc=h.makepc(dispatched||stage==S::Finish?f.next:point(t).location);if(h.cycles-before!=cost)throw std::runtime_error("Panel version clocks differ");return true;}}

